export function materialsForProfessionalLesson(lessonId: string): LessonMaterials | undefined {
  const entry = PROFESSIONAL_MATERIALS.find((m) => m.lessonId === lessonId);
  if (!entry) return undefined;
  return { vocab: entry.vocab, exercises: entry.exercises };
}
